//! Negated-prose false positives for [`crate::core::hash::content_has_alef_marker`].
//!
//! `MARKER_SUBSTRING`/`ALTERNATE_MARKER_SUBSTRINGS` are matched by pure case-insensitive
//! substring containment (`line_has_marker`), with no negation handling at all before this
//! module's fix. A header line that DENIES alef authorship -- `// This file is not generated
//! by alef` -- still contains the literal substring `"generated by alef"`, so it was accepted
//! as a real ownership claim. That claim decides whether alef's write guard is willing to
//! overwrite the file (`write_files_report`, `src/cli/pipeline/generate/write.rs`), so a false
//! positive here is a data-loss path: alef would treat a file it explicitly does NOT own as
//! something it may freely regenerate over.
//!
//! # Negation forms covered
//!
//! Only a single negation-cue word immediately (no intervening punctuation or words)
//! preceding the matched substring, checked case-insensitively:
//! `not`, `never`, `isn't`, `wasn't`, `aren't`, `weren't`, `doesn't`, `didn't` (see
//! `NEGATION_CUES`). This covers, for both `MARKER_SUBSTRING` and each
//! `ALTERNATE_MARKER_SUBSTRINGS` entry:
//!
//! - `"... is not generated by alef"` / `"... was never generated by alef"`
//! - contracted forms: `"isn't generated by alef"`, `"wasn't managed by alef"`, ...
//! - any capitalization of the cue word (`NOT`, `Not`, `Isn't`, ...)
//! - the cue preceding a word the phrase begins *inside*, rather than the phrase itself:
//!   `"is NOT regenerated by alef"`, `"is not auto-generated by alef"`. The needle
//!   `"generated by alef"` starts mid-word in both, so the word immediately before the match
//!   offset is the fragment `"re"`/`"auto-"` and the real cue sits one word further left.
//!
//! # Negation forms deliberately NOT covered
//!
//! Scoped narrow on purpose: this is a heuristic over free text, and widening it risks the
//! opposite, worse failure -- a false NEGATIVE that makes alef refuse to manage a file it
//! genuinely authored (see the module doc on `NEGATION_CUES` for why over-engineering this is
//! not free). Explicitly out of scope:
//!
//! - A negation cue separated from the phrase by other words or punctuation:
//!   `"This file was not, in any real sense, generated by alef"` -- the cue is not the single
//!   word immediately before the match.
//! - A negation cue appearing later in the sentence rather than immediately before the phrase:
//!   `"Generated by alef? Not exactly."` -- two clauses, no adjacency to negate.
//! - A negation spanning a line break: `"This file is not\ngenerated by alef"` -- matches
//!   `line_has_marker`'s own single-line scope, unchanged by this fix.
//! - Typographic (curly) apostrophes in contractions: `"isn\u{2019}t generated by alef"` --
//!   only the plain ASCII `'` is recognized, matching every other ASCII-only assumption this
//!   module already documents (`contains_ignore_ascii_case`).
//! - Synonym negations that never contain the marker substring at all, e.g. "does not
//!   originate from alef" -- there is no false positive to correct there in the first place,
//!   since `line_has_marker` never matched that text to begin with.
//!
//! A file landing in one of these uncovered shapes was already refused as frozen before this
//! fix (a human reviews it either way); this closes the specific, verified case where the
//! substring test alone made alef believe a denial was a claim.

use crate::core::hash::content_has_alef_marker;

/// The confirmed live example: a comment that explicitly disclaims alef authorship must not be
/// read as a marker.
#[test]
fn a_line_explicitly_denying_alef_authorship_is_not_a_marker() {
    assert!(!content_has_alef_marker(
        "// This file is not generated by alef — hand-written, do not overwrite.\nfn keep_me() {}\n"
    ));
}

/// Table of covered negation shapes: cue word (any of `NEGATION_CUES`), any capitalization,
/// against both `MARKER_SUBSTRING` and every `ALTERNATE_MARKER_SUBSTRINGS` entry.
#[test]
fn covered_negation_cues_before_every_marker_substring_are_rejected() {
    let cues = [
        "not", "NOT", "Not", "never", "Never", "isn't", "Isn't", "ISN'T", "wasn't", "Wasn't", "aren't", "weren't",
        "doesn't", "didn't",
    ];
    let phrases = ["generated by alef", "managed by alef", "regenerate with `alef"];

    for cue in cues {
        for phrase in phrases {
            let line = format!("// This is {cue} {phrase}.\n");
            assert!(
                !content_has_alef_marker(&line),
                "expected `{cue} {phrase}` to be recognized as a denial, not a marker claim; got a marker for:\n{line}"
            );
        }
    }
}

/// Negative-of-the-negative control: a marker claim with no negation cue anywhere near it must
/// still be recognized. Without this, a predicate that rejected everything containing "not"
/// anywhere would satisfy the assertions above and look like a fix.
#[test]
fn an_unnegated_marker_is_still_recognized() {
    assert!(content_has_alef_marker(
        "// This file is auto-generated by alef — DO NOT EDIT.\nfn hello() {}\n"
    ));
    assert!(content_has_alef_marker(
        "# Brewfile — managed by alef. DO NOT EDIT.\nbrew \"cmake\"\n"
    ));
}

/// "DO NOT EDIT" sits in the same header line as the real marker in every shipped spelling
/// (`STANDARD_HEADER_LINE` itself). The negation cue must be scoped to the word immediately
/// before the matched phrase, not to "any negation word anywhere on the line" -- otherwise
/// alef's own standard header would defeat its own marker.
#[test]
fn a_negation_word_elsewhere_on_the_line_does_not_defeat_a_real_marker() {
    assert!(content_has_alef_marker(
        "// This file is auto-generated by alef — DO NOT EDIT.\n"
    ));
    assert!(content_has_alef_marker(
        "// generated by alef. Do not edit — never hand-modify this file.\n"
    ));
}

/// The second confirmed live example, and the reason the negation window has to look past the
/// word the match starts inside: this exact line sits at the top of a consumer's hand-written
/// `dispatch.rs`, and alef stamped a hash into the middle of its `//!` doc block because
/// `"generated by alef"` matched inside `"regenerated"`, leaving the fragment `"re"` -- not
/// `"NOT"` -- as the word the cue check inspected. ~keep
#[test]
fn a_denial_whose_phrase_starts_mid_word_is_not_a_marker() {
    assert!(!content_has_alef_marker(
        "//! Hand-written wasm-bindgen dispatch glue.\n         //!\n         //! This module is NOT regenerated by alef. It owns the JS-host integration\n         //! boundary: converting `JsValue` requests into `http::Request`.\n"
    ));
}

/// The same miss reached through a hyphenated compound rather than a prefix: `"generated by
/// alef"` starts inside `"auto-generated"`, so the cue check must traverse the hyphen to reach
/// `"not"`. Pinned separately because it is a different word-boundary rule (`-` is punctuation,
/// not a letter) and fixing one form does not imply the other. ~keep
#[test]
fn a_denial_before_a_hyphenated_compound_is_not_a_marker() {
    assert!(!content_has_alef_marker(
        "// This file is not auto-generated by alef; edit it by hand.\n"
    ));
    assert!(!content_has_alef_marker(
        "// This file was never re-generated by alef.\n"
    ));
}

/// Control for both tests above: backing up over the containing word must not swallow a
/// *legitimate* header, whose phrase also starts mid-word in every shipped spelling
/// (`Auto-generated by alef`). Without this, a fix that simply widened the window until the
/// denials passed would silently unclaim every generated file in every consumer repo. ~keep
#[test]
fn the_standard_hyphenated_header_is_still_a_marker() {
    assert!(content_has_alef_marker(
        "// Auto-generated by alef — DO NOT EDIT\n\npackage dev.spikard;\n"
    ));
    assert!(content_has_alef_marker("# This file is auto-generated by alef.\n"));
    assert!(content_has_alef_marker("// Regenerated by alef on every build.\n"));
}

/// Deliberately uncovered: a negation cue separated from the marker phrase by intervening
/// words is not detected, so this remains a (documented, accepted) false positive. Pinned so a
/// future change to the negation window is a deliberate, visible decision rather than an
/// accidental behavior change.
#[test]
fn a_non_adjacent_negation_is_a_documented_gap_not_a_regression() {
    assert!(
        content_has_alef_marker("// This file was not, in any real sense, generated by alef\n"),
        "documented gap: a negation cue must be the single word immediately before the phrase; \
         if this now fails, the widening was intentional and this test should be updated to say so"
    );
}

/// Deliberately uncovered: a typographic (curly) apostrophe contraction is not recognized as a
/// negation cue, matching this module's ASCII-only scope. Pinned for the same reason as above.
#[test]
fn a_curly_apostrophe_contraction_is_a_documented_gap_not_a_regression() {
    assert!(
        content_has_alef_marker("// This file isn\u{2019}t generated by alef\n"),
        "documented gap: only the plain ASCII apostrophe is recognized; if this now fails, the \
         widening was intentional and this test should be updated to say so"
    );
}
